 loadLibrary().then(M=>{if(closed||!canvas.isConnected)return;api=M;map=new M.Map({container:canvas,style:mapStyle(mode),center:point?[point.longitude,point.latitude]:[39.8,23],zoom:point?13:4,minZoom:2,maxZoom:19,maxPitch:65,attributionControl:false,locale:{'NavigationControl.ZoomIn':'Приблизить','NavigationControl.ZoomOut':'Отдалить'},renderWorldCopies:true,dragRotate:true,touchZoomRotate:true,pitchWithRotate:true,refreshExpiredTiles:true});map.addControl(new M.AttributionControl({compact:true}));map.addControl(new M.NavigationControl({showCompass:false}),'top-left');map.touchZoomRotate?.enableRotation();overlay=doc.createElementNS('http://www.w3.org/2000/svg','svg');overlay.classList.add('qibla-map-overlay');overlay.setAttribute('aria-hidden','true');overlay.innerHTML='<path stroke="#dcc58e" stroke-width="14" opacity=".18"/><path stroke="#142039" stroke-width="8"/><path stroke="#dcc58e" stroke-width="4"/><path stroke="#fff3cc" stroke-width="1" opacity=".7"/><circle r="15" fill="#dcc58e" opacity=".18"/><circle r="6" fill="#dcc58e" stroke="#fff3cc" stroke-width="2"/>';canvas.append(overlay);map.on('style.load',decorate);map.on('move',paintRay);map.on('moveend',update);map.on('click',e=>{const next=mapPoint(e.lngLat.lat,e.lngLat.lng);if(!next)return;cancelLocation();point=next;label='Выбранная точка';update();});map.on('error',event=>{console.warn('SALAH map resource:',event.error?.message||'Unknown map error');if(!closed)status.textContent='Часть карты не загрузилась. Попробуйте другой вид карты или проверьте интернет.';});
 }).catch(async()=>{map?.remove();map=null;if(closed)return;try{const module=await loadFallback();if(closed)return;fallback=module.mountQiblaMap(host,{city,getPosition});const note=doc.createElement('p');note.className='qibla-map-3d-note';note.textContent='На этом устройстве 3D недоступно. Открыта плоская карта.';host.append(note);}catch{if(!closed)status.textContent='Карта недоступна. Проверьте интернет и откройте её ещё раз.';}});
