 host.querySelector('#qibla-map-north').onclick=()=>map?.jumpTo({bearing:0});host.querySelector('#qibla-map-left').onclick=()=>map?.jumpTo({bearing:map.getBearing()-30});host.querySelector('#qibla-map-right').onclick=()=>map?.jumpTo({bearing:map.getBearing()+30});
 locate.onclick=async()=>{if(!map||closed||locating)return;const id=++request;locating=new AbortController();locate.disabled=true;status.textContent='Определяем ваше местоположение…';try{const position=await getPosition({signal:locating.signal,geolocation:{getCurrentPosition:(ok,fail,options)=>navigator.geolocation.getCurrentPosition(ok,fail,{...options,enableHighAccuracy:true,maximumAge:0})}});if(closed||id!==request)return;const next=mapPoint(position.coords.latitude,position.coords.longitude);if(!next)throw Error();point=next;accuracy=Number.isFinite(position.coords.accuracy)?Math.max(0,position.coords.accuracy):0;label='Ваше местоположение'+(accuracy?' · точность ±'+Math.round(accuracy)+' м':'');map.jumpTo({center:[point.longitude,point.latitude],zoom:accuracy>300?14:17});update();}catch(error){if(!closed&&id===request)status.textContent=error?.code===1?'Доступ к местоположению закрыт. Выберите дом касанием карты.':'Не удалось определить место. Выберите дом касанием карты.';}finally{if(id===request){locating=null;locate.disabled=false;}}};
